function isDangerousIP($ip) {
    $ipLong = ip2long($ip);
    if ($ipLong === false) {
        return true; // Treat invalid IPs as dangerous
    }

    $ranges = [
        ['10.0.0.0', '10.255.255.255'],           // 10.0.0.0/8
        ['127.0.0.0', '127.255.255.255'],         // 127.0.0.0/8 (loopback)
        ['169.254.0.0', '169.254.255.255'],       // 169.254.0.0/16 (link-local + cloud metadata)
        ['172.16.0.0', '172.31.255.255'],         // 172.16.0.0/12
        ['192.168.0.0', '192.168.255.255'],       // 192.168.0.0/16
        ['224.0.0.0', '239.255.255.255'],         // 224.0.0.0/4 (multicast)
        ['240.0.0.0', '255.255.255.255'],         // 240.0.0.0/4 (reserved)
        ['0.0.0.0', '0.255.255.255'],             // 0.0.0.0/8
    ];

    foreach ($ranges as [$start, $end]) {
        $startLong = ip2long($start);
        $endLong = ip2long($end);
        if ($ipLong >= $startLong && $ipLong <= $endLong) {
            return true;
        }
    }
    return false;
}
```

